function iconHostOf(baseURL) {
    const text = String(baseURL || '').trim();
    if (!text) return '';
    const match = text.match(/^[a-zA-Z][a-zA-Z0-9+.-]*:\/\/([^/?#]+)/);
    const hostport = match ? match[1] : text.split('/')[0];
    if (!hostport) return '';
    const at = hostport.lastIndexOf('@');
    let host = at >= 0 ? hostport.slice(at + 1) : hostport;
    const colon = host.lastIndexOf(':');
    if (colon > 0 && /^\d+$/.test(host.slice(colon + 1))) host = host.slice(0, colon);
    return host.toLowerCase();
}

export function providerIconKeyForHost(baseURL) {
    const host = iconHostOf(baseURL);
    if (!host) return '';
    for (const [known, key] of HOST_ICONS) {
        if (host === known || host.endsWith('.' + known)) return key;
    }
    return '';
}

export function providerIconKeyForName(name) {
    const text = String(name || '').toLowerCase();
    if (!text) return '';
    for (const [keyword, key] of NAME_ICONS) {
        if (text.includes(keyword)) return key;
    }
    return '';
}

// 解析账号的图标键：host 精确优先，名称关键词兜底；都未命中返回 ''（调用方画首字母瓦片）。
export function resolveProviderIcon(profile) {
    if (!profile) return '';
    const byHost = providerIconKeyForHost(profile.baseURL);
    if (byHost) return byHost;
    return providerIconKeyForName(profile.name);
}

// 每次渲染的渐变/clip id 后缀：品牌 SVG 里 defs 的 id（如 qwen 的渐变）是固定值，
// 页面上多个账号卡片各渲染一份就会 id 重复，url(#id) 指向文档中首个实例；首个实例被
// 列表重绘移除后引用悬空 → 图标渲染不出（千问图标曾因此消失）。逐个实例改写唯一 id。
let iconRenderSeq = 0;

// 图标的完整 <svg> 字符串；fill 默认 currentColor（随主题文字色），Kimi 等自带品牌色
// path 保留其 fill 属性原样输出。未注册返回 ''。
export function providerIconSvg(key, size) {
    const icon = PROVIDER_ICONS[key];
    if (!icon) return '';
    const px = Number(size) > 0 ? Math.round(Number(size)) : 18;
    let body = icon.body;
    if (/\bid="|url\(#/.test(body)) {
        const suffix = '-r' + (++iconRenderSeq);
        // 先给所有 defs id 加后缀，再同步所有 url(#id) 引用，保证同一 svg 内自洽。
        body = body.replace(/\bid="([^"]+)"/g, (_m, id) => 'id="' + id + suffix + '"')
            .replace(/url\(#([^)]+)\)/g, (_m, id) => 'url(#' + id + suffix + ')');
    }
    return '<svg viewBox="' + icon.viewBox + '" width="' + px + '" height="' + px +
        '" fill="currentColor" aria-hidden="true">' + body + '</svg>';
}

// cc-switch 同款：按 Unicode 码位安全取首字母（≤2 字符，大写）——emoji / UTF-16
// 代理对不会被截半。全空返回 'AI'。
export function getProviderInitials(name) {
    const words = String(name || '').trim().split(/\s+/).filter(Boolean);
    const initials = Array.from(
        words
            .map((word) => Array.from(word)[0])
            .filter(Boolean)
            .join(''),
    )
        .slice(0, 2)
        .join('')
        .toUpperCase();
    return initials || 'AI';
}

// 图标瓦片 HTML：命中注册表 → 主题色品牌矢量；未命中 → 首字母瓦片（accent 底色）。
// 调用方用 innerHTML 挂进容器；darkTheme 参数保留占位（品牌矢量走 currentColor 自适应主题）。
export function providerIconTileHtml(profile, size) {
    const px = Number(size) > 0 ? Math.round(Number(size)) : 20;
    const key = resolveProviderIcon(profile);
    if (key && PROVIDER_ICONS[key]) {
        return '<span class="ai-picon ai-picon-svg" style="width:' + px + 'px;height:' + px + 'px">' +
            providerIconSvg(key, Math.max(12, px - 6)) + '</span>';
    }
    const initials = getProviderInitials(profile && profile.name);
    return '<span class="ai-picon ai-picon-fallback" style="width:' + px + 'px;height:' + px + 'px">' +
        escapeHtml(initials) + '</span>';
}


